"""Secrets generated by the Fabric network must stay out of Git."""

from __future__ import annotations

import subprocess
from pathlib import Path

SECRET_SUFFIXES = (".pem", ".key", ".crt")
GENERATED_PARTS = {
    "organizations",
    ".runtime",
    "channel-artifacts",
    "wallet",
    "__pycache__",
}


def _tracked(repo_root: Path) -> list[str]:
    output = subprocess.check_output(
        ["git", "ls-files"],
        cwd=repo_root,
        text=True,
        encoding="utf-8",
    )
    return [line.strip() for line in output.splitlines() if line.strip()]


def test_tracked_files_contain_no_wallet_key_or_certificate(repo_root: Path) -> None:
    offenders = []
    for path in _tracked(repo_root):
        lowered = path.lower()
        if (
            lowered.endswith((*SECRET_SUFFIXES, "_sk", "ca.env"))
            or "/wallet/" in lowered
            or lowered.startswith(
                (
                    "fabric/organizations/",
                    "fabric/.runtime/",
                    "fabric/channel-artifacts/",
                )
            )
        ):
            offenders.append(path)
    assert offenders == []


def test_shell_scripts_are_executable_in_the_git_index(repo_root: Path) -> None:
    """AUD-027: the documented `./fabric/network.sh` and `./scripts/test-l.sh` need mode 100755.

    This host has core.fileMode=false, so Git never records the bit from a Windows
    checkout; set it with `git update-index --chmod=+x <file>` (tracked) or
    `git add --chmod=+x <file>` (new).
    """
    output = subprocess.check_output(
        ["git", "ls-files", "-s", "--", "*.sh"],
        cwd=repo_root,
        text=True,
        encoding="utf-8",
    )
    entries = [line.split("\t", 1) for line in output.splitlines() if "\t" in line]
    assert entries, "no shell script is tracked"
    offenders = [path for mode, path in entries if not mode.startswith("100755")]
    assert offenders == []


def test_generated_fabric_paths_are_ignored(repo_root: Path) -> None:
    samples = [
        "fabric/organizations/peerOrganizations/org1.example.com/peers/peer0/tls/server.key",
        "fabric/organizations/fabric-ca/org1/ca-cert.pem",
        "fabric/.runtime/ca.env",
        "fabric/channel-artifacts/medtrace.block",
        "fabric/wallet/app-user/cert.pem",
    ]
    for sample in samples:
        result = subprocess.run(
            ["git", "check-ignore", "-q", "--", sample],
            cwd=repo_root,
            check=False,
        )
        assert result.returncode == 0, sample


def _source_files(root: Path) -> list[Path]:
    if root.is_file():
        return [root]
    selected: list[Path] = []
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(root)
        if any(part in GENERATED_PARTS for part in relative.parts):
            continue
        if path.suffix.lower() in SECRET_SUFFIXES or path.name.endswith("_sk"):
            continue
        selected.append(path)
    return selected


def test_compose_and_scripts_do_not_embed_sample_passwords_or_private_keys(
    repo_root: Path,
) -> None:
    roots = [repo_root / "fabric", repo_root / "scripts" / "test-l.sh"]
    banned = ("adminpw", "peer0pw", "BEGIN PRIVATE KEY", "BEGIN EC PRIVATE KEY")
    for root in roots:
        for path in _source_files(root):
            try:
                text = path.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                continue
            for secret in banned:
                if secret in text:
                    raise AssertionError(
                        f"{path.relative_to(repo_root)} contains a banned credential marker"
                    )
